import app from 'flarum/forum/app';
import { trail, teamsCrumb } from '../waymark';
import Page from 'flarum/common/components/Page';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Link from 'flarum/common/components/Link';
import extractText from 'flarum/common/utils/extractText';
import crestUrl from '../crest';
/**
 * Every club this site holds, grouped by conference or division.
 *
 * Each club arrives with the heading it is filed under (`group`), worked out
 * on the server; this page only collects them and puts the biggest first.
 */
export default class RosterIndexPage extends Page {
  loading = true;
  leagues = [];
  league = '';
  conferences = [];
  oninit(vnode) {
    super.oninit(vnode);
    app.history.push('roster', extractText(app.translator.trans('ernestdefoe-roster.forum.title')));
    this.load();
  }
  load() {
    this.leagues = app.forum.attribute('rosterLeagues') || [];
    const wanted = m.route.param('league') || '';
    this.league = this.leagues.some(l => l.key === wanted) ? wanted : this.leagues[0]?.key || '';
    if (!this.league) {
      this.loading = false;
      return;
    }
    this.loading = true;
    app.store.find('roster-teams', {
      filter: {
        league: this.league
      },
      page: {
        limit: 200
      }
    }).then(teams => {
      this.conferences = RosterIndexPage.group(teams);
    }).catch(() => {
      // app.request has already shown the error; the page shows its empty state.
      this.conferences = [];
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }

  /**
   * Conferences by size, then name — a fixed list of the power leagues is a
   * maintenance problem that comes due every time realignment happens.
   */
  static group(teams) {
    const byName = new Map();
    teams.forEach(team => {
      const name = team.group();
      byName.set(name, [...(byName.get(name) || []), team]);
    });
    return [...byName.entries()].map(_ref => {
      let [name, list] = _ref;
      return {
        name,
        teams: list
      };
    }).sort((a, b) => b.teams.length - a.teams.length || a.name.localeCompare(b.name));
  }
  view() {
    return m("div", {
      className: "RosterPage"
    }, trail([teamsCrumb(false)]), m("div", {
      className: "container"
    }, this.head(), this.loading ? m(LoadingIndicator, null) : this.conferences.length === 0 ? m("p", {
      className: "RosterPage-empty"
    }, app.translator.trans('ernestdefoe-roster.forum.empty')) : this.conferences.map(group => this.conference(group))));
  }
  head() {
    return m("div", {
      className: "RosterPage-head"
    }, m("h1", null, app.translator.trans('ernestdefoe-roster.forum.title')), m("p", {
      className: "RosterPage-intro"
    }, app.translator.trans('ernestdefoe-roster.forum.intro')), this.leagues.length > 1 && m("div", {
      className: "RosterPage-leagues"
    }, this.leagues.map(l => m(Link, {
      className: 'Button Button--small' + (l.key === this.league ? ' Button--primary' : ''),
      href: app.route('roster.index') + `?league=${encodeURIComponent(l.key)}`
    }, l.name))));
  }
  conference(group) {
    return m("section", {
      className: "RosterConference"
    }, m("h2", null, group.name, m("span", {
      className: "RosterConference-count"
    }, app.translator.trans('ernestdefoe-roster.forum.team_count', {
      count: group.teams.length
    }))), m("div", {
      className: "RosterGrid"
    }, group.teams.map(team => m(Link, {
      className: "RosterCard",
      href: app.route('roster.team', {
        slug: team.slug()
      })
    }, team.logo() ? m("img", {
      className: "RosterCard-crest",
      src: crestUrl(team.logo(), 34),
      alt: "",
      loading: "lazy",
      decoding: "async"
    }) : m("span", {
      className: "RosterCard-crest RosterCard-crest--none"
    }), m("span", {
      className: "RosterCard-name"
    }, team.name(), team.mascot() ? m("span", {
      className: "RosterCard-mascot"
    }, team.mascot()) : null)))));
  }
}
flarum.reg.add('ernestdefoe-roster', 'forum/components/RosterIndexPage', RosterIndexPage);